function hargaAkhir(b: Barang): number {
  return b.harga - (b.diskon ?? 0);
}
console.log(hargaAkhir({ nama: "Produk-907", harga: 22000, diskon: 1500 }));
```
Operator `?? 0` memberi nilai cadangan nol saat `diskon` kosong; di sini hasilnya `20500`.

