interface Barang { nama: string; harga: number; diskon?: number; }
function hargaAkhir(b: Barang): number {
  return b.harga - (b.diskon ?? 0);
}
console.log(hargaAkhir({ nama: "Produk-160", harga: 28000, diskon: 1500 }));
```
Operator `?? 0` memberi nilai cadangan nol saat `diskon` kosong; di sini hasilnya `26500`.

